def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(ax, ay, bx, by):
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position"))
    ox, oy = safe_pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(sx, sy, ox, oy)

        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = corners[0]
        best_score = None
        for c in corners:
            sc = manhattan(c, (ox, oy))
            if best_score is None or sc > best_score:
                best_score = sc
                target = c
        return step_toward(sx, sy, target[0], target[1])

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("neutral_cells")
        if not targets:
            targets = []

        if targets:
            best = None
            best_score = None
            for t in targets:
                tx, ty = safe_pos(t, (sx, sy))
                score = manhattan((sx, sy), (tx, ty))
                if best_score is None or score < best_score:
                    best_score = score
                    best = (tx, ty)
            if best is not None:
                return step_toward(sx, sy, best[0], best[1])

        center_x = (gw - 1) / 2 if gw else sx
        center_y = (gh - 1) / 2 if gh else sy
        return step_toward(sx, sy, int(center_x), int(center_y))

    resources = observation.get("resources") or observation.get("resource_cells") or []
    if resources:
        best = None
        best_score = None
        for r in resources:
            rx, ry = safe_pos(r, (sx, sy))
            score = manhattan((sx, sy), (rx, ry))
            if ox != sx or oy != sy:
                score -= 0.25 * manhattan((ox, oy), (rx, ry))
            if best_score is None or score < best_score:
                best_score = score
                best = (rx, ry)
        if best is not None:
            return step_toward(sx, sy, best[0], best[1])

    if ox != sx or oy != sy:
        dx = clamp_step(sx - ox)
        dy = clamp_step(sy - oy)
        if dx == 0 and dy == 0:
            if gw and gh:
                return step_toward(sx, sy, gw // 2, gh // 2)
            return [0, 0]
        return [dx, dy]

    if gw and gh:
        return step_toward(sx, sy, gw // 2, gh // 2)

    return [0, 0]

